#include <bits/stdc++.h>
#include <boost/multiprecision/cpp_int.hpp>
using namespace std; using boost::multiprecision::cpp_int; using u128=unsigned __int128;
struct Pt{int x,y; bool operator<(Pt const&o)const{return tie(x,y)<tie(o.x,o.y);}}; struct Lab{int k;Pt a,b;};
vector<Pt>C; map<pair<int,int>,int>I; vector<unsigned long long>P3; vector<Lab>L;
int gv(uint64_t s,int i){return (s/P3[i])%3;} uint64_t sv(uint64_t s,int i,int v){return s+(long long)(v-gv(s,i))*P3[i];}
vector<int> ni(Pt p){vector<int>r;int dx[4]={1,-1,0,0},dy[4]={0,0,1,-1};for(int z=0;z<4;z++){auto it=I.find({p.x+dx[z],p.y+dy[z]});if(it!=I.end())r.push_back(it->second);}return r;}
vector<pair<uint64_t,int>> tr(uint64_t s,int li){auto l=L[li];map<uint64_t,int>o;if(!l.k){int i=I[{l.a.x,l.a.y}];if(gv(s,i))return{{s,72}};auto a=sv(s,i,1);vector<int>os;for(int q:ni(l.a))if(gv(a,q)==2)os.push_back(q);if(os.empty())return{{a,72}};int w=72/os.size();for(int q:os)o[sv(sv(a,i,0),q,0)]+=w;}else{int u=I[{l.a.x,l.a.y}],v=I[{l.b.x,l.b.y}];if(gv(s,u)||gv(s,v))return{{s,36}};auto a=sv(sv(s,u,2),v,2);vector<int>cu,cv;for(int q:ni(l.a))if(gv(a,q)==1)cu.push_back(q);for(int q:ni(l.b))if(gv(a,q)==1)cv.push_back(q);if(cu.empty())cu.push_back(-1);if(cv.empty())cv.push_back(-1);int d=cu.size()*cv.size();if(36%d){cerr<<"bad branch denom\n";exit(2);}int w=36/d;for(int qu:cu)for(int qv:cv){auto t=a;if(qu>=0)t=sv(sv(t,u,0),qu,0);if(qv>=0)t=sv(sv(t,v,0),qv,0);o[t]+=w;}}return{ o.begin(),o.end()};}
int TI[6]; bool target(uint64_t s){for(int i:TI)if(gv(s,i))return false;return true;}
unordered_map<uint64_t,u128>M[9]; u128 A(int n,uint64_t s){auto &m=M[n];auto it=m.find(s);if(it!=m.end())return it->second;u128 z=0;if(!n)z=target(s);else for(int i=0;i<(int)L.size();i++)for(auto [t,w]:tr(s,i))z+=(u128)w*A(n-1,t);m.emplace(s,z);return z;}
string s128(u128 x){if(!x)return"0";string s;while(x){s.push_back('0'+x%10);x/=10;}reverse(s.begin(),s.end());return s;} cpp_int pw(cpp_int a,int n){cpp_int r=1;while(n--)r*=a;return r;}
int main(){vector<pair<int,int>> cc={{-2,0},{-2,1},{-1,-1},{-1,0},{-1,1},{-1,2},{0,-2},{0,-1},{0,0},{0,1},{0,2},{0,3},{1,-1},{1,0},{1,1},{1,2},{2,0},{2,1}};for(auto[x,y]:cc)C.push_back({x,y});sort(C.begin(),C.end());for(int i=0;i<(int)C.size();i++)I[{C[i].x,C[i].y}]=i;P3.resize(30);P3[0]=1;for(int i=1;i<30;i++)P3[i]=P3[i-1]*3ULL;
auto co=[&](int x,int y){L.push_back({0,{x,y},{0,0}});};auto o2=[&](int a,int b,int c,int d){Pt u{a,b},v{c,d};if(v<u)swap(u,v);L.push_back({1,u,v});};
co(0,0);o2(-1,1,0,1);co(0,1);co(1,0);o2(-1,0,-1,1);o2(0,0,0,1);co(-1,1);o2(-1,0,0,0);co(-1,0);o2(0,0,1,0);co(0,-1);o2(0,-1,0,0);co(1,1);o2(0,1,1,1);o2(1,0,1,1);co(0,2);o2(0,1,0,2);
vector<pair<int,int>>tt={{-1,0},{-1,1},{0,0},{0,1},{1,0},{1,1}};for(int j=0;j<6;j++)TI[j]=I[tt[j]];set<pair<int,int>>F={{-2,0},{-2,1},{-1,0},{-1,1},{0,0},{0,1}};vector<int>V;for(int i=0;i<(int)C.size();i++)if(!F.count({C[i].x,C[i].y}))V.push_back(i);long long tot=1;for(int _:V)tot*=3;vector<uint64_t>in;for(long long code=0;code<tot;code++){long long q=code;vector<int>x(C.size(),0);for(int i:V){x[i]=q%3;q/=3;}bool ok=1;for(int i=0;i<(int)C.size()&&ok;i++){int dx[2]={1,0},dy[2]={0,1};for(int z=0;z<2;z++){auto it=I.find({C[i].x+dx[z],C[i].y+dy[z]});if(it!=I.end()&&((x[i]==1&&x[it->second]==2)||(x[i]==2&&x[it->second]==1))){ok=0;break;}}}if(ok){uint64_t s=0;for(int i=0;i<(int)C.size();i++)s+=P3[i]*x[i];in.push_back(s);}}
if(in.size()!=45943){cerr<<"bad init count "<<in.size()<<"\n";return 3;} cpp_int aa=43,bb=20,H=36*214;unsigned long long fact[9];fact[0]=1;for(int n=1;n<=8;n++)fact[n]=fact[n-1]*n;vector<cpp_int>cf(9);for(int n=0;n<=8;n++)cf[n]=pw(aa,n)*pw(bb,8-n)*pw(H,8-n)*(fact[8]/fact[n]);bool first=1;cpp_int best;uint64_t arg=0;vector<u128>bas(9),mins(9,~(u128)0);for(uint64_t s:in){cpp_int num=0;vector<u128>as(9);for(int n=0;n<=8;n++){as[n]=A(n,s);if(as[n]<mins[n])mins[n]=as[n];num+=cpp_int(s128(as[n]))*cf[n];}if(first||num<best){first=0;best=num;arg=s;bas=as;}}
cout<<"PASS finite exact DP core\n"<<"stable_initial_states="<<in.size()<<"\nlabels="<<L.size()<<"\nworst_state="<<arg<<"\nMINS=";for(int n=0;n<=8;n++)cout<<s128(mins[n])<<(n<8?",":"\n");cout<<"WORST_A=";for(int n=0;n<=8;n++)cout<<s128(bas[n])<<(n<8?",":"\n");cout<<"POLY_NUM="<<best<<"\nPOLY_DEN="<<pw(bb,8)*pw(H,8)*fact[8]<<"\n";}
